  <script>
  function wrapPricingTables() {
    const tables = document.querySelectorAll('.pricing-table.new');
    tables.forEach((table) => {
      // Prevent double wrapping
      if (table.classList.contains('wrapped')) return;
      const items = Array.from(table.children);
      table.innerHTML = '';
      for (let i = 0; i < items.length; i += 4) {
        const row = document.createElement('div');
        row.classList.add('pricing-table-row');
        items.slice(i, i + 4).forEach((item) => {
          row.appendChild(item);
        });
        table.appendChild(row);
      }
      table.classList.add('wrapped');
    });
  }
  // Run on page load
  document.addEventListener('DOMContentLoaded', function () {
    wrapPricingTables();
  });
  // Run again when tab is clicked
  document.querySelectorAll('.w-tab-link').forEach((tab) => {
    tab.addEventListener('click', function () {
      setTimeout(() => {
        wrapPricingTables();
      }, 100); // small delay for Webflow animation
    });
  });
</script>
