  <script>
  $(document).ready(function () {
    var $main = $('.work-gallery-main');
    var $thumbs = $('.work-gallery-thumbs');
    var realSlides = $main.find('.work-slide').length;
    if (realSlides === 0) return;
    // Init main slider WITHOUT asNavFor
    $main.slick({
      slidesToShow: 1,
      slidesToScroll: 1,
      arrows: false,
      fade: false,
      infinite: realSlides > 1,
      draggable: true,
      swipe: true,
    });
    // Init thumbs WITHOUT asNavFor and WITHOUT slick movement
    $thumbs.slick({
      slidesToShow: Math.min(realSlides, 3),
      slidesToScroll: 1,
      focusOnSelect: false,
      arrows: false,
      infinite: false,
      draggable: false,
      swipe: false,
    });
    // Lock the thumb track in place — never let it scroll
    $thumbs.find('.slick-track').css({
      transform: 'none',
      transition: 'none',
      width: '100%',
    });
    // Manually handle thumb clicks — only change main image, never move thumbs
    $thumbs.on('click', '.slick-slide', function () {
      var index = $(this).data('slick-index');
      if (index < 0) return; // ignore clones
      $main.slick('slickGoTo', index);
    });
    // Highlight active thumb when main slide changes
    $main.on('afterChange', function (event, slick, currentSlide) {
      // Remove active from all thumbs
      $thumbs.find('.slick-slide').removeClass('slick-current');
      // Add active to matching thumb
      $thumbs.find('.slick-slide[data-slick-index="' + currentSlide + '"]').addClass('slick-current');
      // Update counter
      $('.current').text(String(currentSlide + 1).padStart(2, '0'));
      // Keep thumb track locked
      $thumbs.find('.slick-track').css('transform', 'none');
    });
    // Counter init
    var total = realSlides;
    $('.total').text(String(total).padStart(2, '0'));
    $('.current').text('01');
    // Initial active thumb highlight
    $thumbs.find('.slick-slide[data-slick-index="0"]').addClass('slick-current');
    // Final position lock
    setTimeout(function () {
      $main.slick('setPosition');
      $thumbs.find('.slick-track').css({
        transform: 'none',
        transition: 'none',
      });
    }, 100);
  });
</script>
  <script>
  (function () {
    /* ── Element refs ───────────────────────────────────────────── */
    const overlay = document.getElementById('bt-popup-overlay');
    const modal = document.getElementById('bt-popup-modal');
    const closeBtn = document.getElementById('bt-popup-close');
    const skipBtn = document.getElementById('bt-popup-skip');
    const trigger = document.getElementById('bt-popup-trigger');
    if (!overlay || !modal) return; // safety check
    /* ── Inject animation styles once ──────────────────────────── */
    const style = document.createElement('style');
    style.textContent = `
    #bt-popup-overlay {
      display: none;
      position: fixed;
      inset: 0;
      z-index: 999999;
      align-items: center;
      justify-content: center;
      background: rgba(0, 0, 0, 0.55);
      backdrop-filter: blur(4px);
      -webkit-backdrop-filter: blur(4px);
      padding: 20px;
      transition: opacity 0.25s ease;
    }
    #bt-popup-overlay.is-visible {
      display: flex;
      opacity: 1;
    }
    #bt-popup-overlay.is-hiding {
      opacity: 0;
      pointer-events: none;
    }
    #bt-popup-modal {
      transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1),
                  opacity 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    }
    #bt-popup-modal.is-entering {
      transform: translateY(0px) scale(1);
      opacity: 1;
    }
    #bt-popup-modal.is-hidden {
      transform: translateY(24px) scale(0.97);
      opacity: 0;
    }
  `;
    document.head.appendChild(style);
    /* ── Open ───────────────────────────────────────────────────── */
    function openPopup() {
      // reset modal to hidden start position (no animation yet)
      modal.classList.add('is-hidden');
      modal.classList.remove('is-entering');
      // show overlay instantly
      overlay.style.opacity = '0';
      overlay.style.display = 'flex';
      // lock body scroll
      document.body.style.overflow = 'hidden';
      // next frame: trigger transitions
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          overlay.style.opacity = '1';
          modal.classList.remove('is-hidden');
          modal.classList.add('is-entering');
        });
      });
    }
    /* ── Close ──────────────────────────────────────────────────── */
    function closePopup() {
      // fade out overlay
      overlay.style.opacity = '0';
      // slide modal back down
      modal.classList.remove('is-entering');
      modal.classList.add('is-hidden');
      // after transition ends, fully hide
      setTimeout(() => {
        overlay.style.display = 'none';
        overlay.style.opacity = '';
        document.body.style.overflow = '';
      }, 300);
    }
    /* ── Event listeners ────────────────────────────────────────── */
    // Trigger button opens popup
    if (trigger) trigger.addEventListener('click', openPopup);
    // Close button
    if (closeBtn) closeBtn.addEventListener('click', closePopup);
    // Skip link
    if (skipBtn) skipBtn.addEventListener('click', closePopup);
    // Click outside modal (on dark overlay) closes popup
    overlay.addEventListener('click', function (e) {
      if (e.target === overlay) closePopup();
    });
    // Escape key closes popup
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && overlay.style.display === 'flex') {
        closePopup();
      }
    });
    /* ── Auto-show on page load (optional) ─────────────────────── */
    // Remove or increase the delay (ms) as needed
    // setTimeout(openPopup, 1500);
  })();
</script>
